var SQFT_PER_SPACE = 330;
var MIN_CAPACITY = 10;
var MAX_CAPACITY = 900;
function deriveCapacity(areaSqFt) {
  const raw = Math.round(areaSqFt / SQFT_PER_SPACE / 5) * 5;
  return Math.min(MAX_CAPACITY, Math.max(MIN_CAPACITY, raw));
}
function hashUnit(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0) / 4294967295;
}
function deriveOccupiedFraction(id) {
  return 0.45 + hashUnit(id) * 0.48;
}
